    Bug 1935661 - Reduce space between description and action button in blog, message and security type notifications. r=arschmitz,micahilbery

    Differential Revision: https://phabricator.services.mozilla.com/D231384

diff --git a/mail/themes/shared/mail/inAppNotificationContainer.css b/mail/themes/shared/mail/inAppNotificationContainer.css
index afca22d0fad..4095648c120 100644
--- a/mail/themes/shared/mail/inAppNotificationContainer.css
+++ b/mail/themes/shared/mail/inAppNotificationContainer.css
@@ -95,6 +95,10 @@
       inset-inline-start: 0;
     }

+    & .in-app-notification-description {
+      margin-block-end: 60px;
+    }
+
     @media (prefers-color-scheme: dark) {
       --button-background: linear-gradient(#f5e8ff, #ecd5ff);
       --illustration: var(--illustration-dark);
@@ -189,6 +193,12 @@
     @media (prefers-color-scheme: dark) {
       --content-background: #18181b;
     }
+
+    & .in-app-notification-description {
+      /* Roughly the height of the button. Padding on the button is 12px
+         vertically. */
+      margin-block-end: calc(1.5em + 14px);
+    }
   }

   & .in-app-notification-content {
@@ -297,7 +307,6 @@
     font-size: 0.9rem;
     min-height: 2lh;
     margin: 0;
-    margin-block-end: 60px;
     hyphens: auto;
     max-height: 20lh;
     overflow: auto;
